//
//  Color+App.swift
//  StepKit
//
//  Most colors are auto-generated by Xcode from Asset Catalog.
//  Only define colors here that are NOT auto-generated.
//

import SwiftUI

// MARK: - Color Extension

extension Color {
    // MARK: - Colors NOT auto-generated (define manually)

    /// Glow color for shadows and ambient effects
    /// Note: This colorset exists but Xcode doesn't auto-generate it
    static let glowColor = Color("GlowColor")

    // MARK: - Backgrounds (System Colors)

    /// Card background (adapts to dark mode)
    static let cardBackground = Color(.secondarySystemGroupedBackground)

    /// App background (grouped style)
    static let appBackground = Color(.systemGroupedBackground)
    /// Fondo de una hoja igual al de las pantallas: en oscuro, una hoja «eleva» los grises del
    /// sistema y se veía más claro que el resto. Aquí se fija el nivel base.
    static let sheetBackground = Color(UIColor { tc in
        tc.userInterfaceStyle == .dark ? .black : UIColor.systemGroupedBackground.resolvedColor(with: UITraitCollection(userInterfaceStyle: .light))
    })
    static let sheetRowBackground = Color(UIColor { tc in
        tc.userInterfaceStyle == .dark ? UIColor(red: 0.11, green: 0.11, blue: 0.118, alpha: 1) : .white
    })
}

// MARK: - UIColor Extension for UIKit compatibility

extension UIColor {
    /// Accent highlight for UIKit components (e.g., UICalendarView)
    static let uiAccentHighlight = UIColor { traitCollection in
        traitCollection.userInterfaceStyle == .dark
            ? UIColor(red: 0.40, green: 0.65, blue: 0.90, alpha: 1.0)
            : UIColor(red: 0.55, green: 0.82, blue: 1.0, alpha: 1.0)
    }

    /// Glow color for UIKit components
    static let uiGlowColor = UIColor { traitCollection in
        traitCollection.userInterfaceStyle == .dark
            ? UIColor(red: 0.15, green: 0.45, blue: 0.80, alpha: 1.0)
            : UIColor(red: 0.2, green: 0.6, blue: 1.0, alpha: 1.0)
    }
}
